"""Command-line entry point for the request-latency window report tool."""

import argparse
import sys

import report


def parse_args(argv):
    parser = argparse.ArgumentParser(
        description="Summarize request latency by time window"
    )
    parser.add_argument("logfile", help="Path to access log file")
    parser.add_argument(
        "--window-seconds",
        type=int,
        default=60,
        help="Size of each reporting window in seconds",
    )
    return parser.parse_args(argv)


def load_records(path):
    records = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(",")
            if len(parts) != 3:
                continue
            timestamp_str, path_str, latency_str = parts
            records.append(
                report.Record(
                    timestamp=float(timestamp_str),
                    path=path_str,
                    latency_ms=float(latency_str),
                )
            )
    return records


def main(argv=None):
    args = parse_args(argv if argv is not None else sys.argv[1:])
    records = load_records(args.logfile)
    for line in report.build_report(records, args.window_seconds):
        print(line)


if __name__ == "__main__":
    main()

"""Utilities for splitting a time range into fixed-size reporting windows."""


def _compute_window_count(total_span, window_seconds):
    return int(total_span // window_seconds)


def window_bounds(start_time, end_time, window_seconds):
    """Yield (window_start, window_end) pairs spanning start_time to end_time."""
    total_span = end_time - start_time
    count = _compute_window_count(total_span, window_seconds)
    for i in range(count):
        window_start = start_time + i * window_seconds
        yield (window_start, window_start + window_seconds)


def slice_window(records, window_start, window_end):
    """Return the records whose timestamp falls in [window_start, window_end)."""
    return [r for r in records if window_start <= r.timestamp < window_end]

"""Statistical summaries for grouped latency samples."""


def mean(values):
    if not values:
        return 0.0
    return sum(values) / len(values)


def percentile(values, pct):
    """Return the pct-th percentile of values using the nearest-rank method."""
    if not values:
        return 0.0
    ordered = sorted(values)
    rank = max(1, int(round(pct / 100 * len(ordered))))
    index = min(rank, len(ordered)) - 1
    return ordered[index]


def summarize(records):
    latencies = [r.latency_ms for r in records]
    return {
        "count": len(records),
        "mean_ms": mean(latencies),
        "p50_ms": percentile(latencies, 50),
        "p95_ms": percentile(latencies, 95),
        "p99_ms": percentile(latencies, 99),
    }
